python3 << 'EOF'
import zipfile, re
from xml.etree import ElementTree as ET

M = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

with zipfile.ZipFile('budget.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    rows = []
    for row in root.iter(M+'row'):
        cells = {}
        for c in row.findall(M+'c'):
            ref = c.get('r'); t = c.get('t')
            col = re.match(r'[A-Z]+', ref).group()
            val = None
            if t == 'inlineStr':
                is_ = c.find(M+'is')
                if is_ is not None:
                    val = ''.join(tt.text or '' for tt in is_.iter(M+'t'))
            else:
                v = c.find(M+'v')
                if v is not None:
                    val = v.text
            cells[col] = val
        rows.append(cells)

    # Print full grid in order
    all_cols = []
    for r in rows:
        for k in r:
            if k not in all_cols:
                all_cols.append(k)
    print(' | '.join(all_cols))
    for r in rows:
        print(' | '.join(r.get(c, '') or '' for c in all_cols))
EOF
